mapper.select:

SELECT

FROM submission
WHERE contest_id = #{contestId}
  AND vp_attempt_id IS NULL

    AND user_id = #{currentUserId}


    AND problem_id = #{problemId}


    AND language = #{language}


    AND status = #{status}

ORDER BY id DESC


SELECT
    DATE_FORMAT(create_time, '%Y-%m-%d') AS submitDate,
    COUNT(*) AS submitCount
FROM submission
WHERE user_id = #{userId}
  AND create_time >= #{startTime}
  AND create_time < #{endTime}
GROUP BY DATE_FORMAT(create_time, '%Y-%m-%d')
ORDER BY submitDate ASC

SELECT s.id, s.user_id AS studentId, COALESCE(NULLIF(cs.remark, ''), NULLIF(u.nickname, ''), u.username) AS studentName, s.problem_id AS problemId, p.title AS problemTitle, s.language, s.status, s.score, s.run_time AS runTime, s.run_memory AS runMemory, s.error_message AS errorMessage, s.create_time AS createTime FROM submission s INNER JOIN class_student cs ON cs.student_id = s.user_id AND cs.class_id = #{classId} INNER JOIN problem_list_item pli ON pli.problem_id = s.problem_id AND pli.list_id = #{homeworkId} LEFT JOIN user u ON u.id = s.user_id LEFT JOIN problem p ON p.id = s.problem_id WHERE 1 = 1
AND s.user_id = #{studentId}
AND s.problem_id = #{problemId}
AND s.create_time >= #{startTime}
AND s.create_time <= #{endTime}
ORDER BY s.create_time DESC, s.id DESC

SELECT s.user_id AS userId, t.dimension AS dimension, COUNT(DISTINCT s.problem_id) AS attempted, COUNT(DISTINCT CASE WHEN s.status = 1 THEN s.problem_id END) AS passed, COUNT(DISTINCT CASE WHEN s.status = 1 AND (SELECT COUNT(*) FROM submission s2 WHERE s2.user_id = s.user_id AND s2.problem_id = s.problem_id AND s2.create_time < s.create_time) = 0 THEN s.problem_id END) AS firstTryPassed, COUNT(s.id) AS totalSubmissions FROM submission s JOIN problem_tag pt ON pt.problem_id = s.problem_id JOIN tag t ON t.id = pt.tag_id WHERE s.user_id IN
#{sid}
AND s.create_time >= #{from} AND s.create_time < #{to} AND t.parent_id IS NOT NULL GROUP BY s.user_id, t.dimension


SELECT
    COUNT(*)                                                        AS totalSubmissions,
    COALESCE(SUM(CASE WHEN s.status = 1 THEN 1 ELSE 0 END), 0)     AS acceptedCount,
    COUNT(DISTINCT CASE WHEN s.status = 1 THEN s.problem_id END)    AS acceptedProblemCount,
    COUNT(DISTINCT DATE(s.create_time))                             AS activeDays
FROM submission s
WHERE s.user_id = #{userId}
  AND s.create_time >= #{from}
  AND s.create_time <  #{to}

mapper.sql:
SELECT s.id, s.problem_id, s.status, s.create_time, s.run_time, p.difficulty, ROW_NUMBER() OVER (PARTITION BY s.problem_id ORDER BY s.create_time ASC, s.id ASC) AS rn FROM submission s INNER JOIN problem p ON p.id = s.problem_id AND p.is_deleted = 0 WHERE s.user_id = #{userId} AND s.status != 0 AND COALESCE(s.judge_phase, '') != 'FAILED'
AND s.create_time >= #{from}
AND s.create_time < #{to}

mapper.select:

SELECT
    COUNT(*)                                                        AS totalSubmissions,
    COALESCE(SUM(CASE WHEN s.status = 1 THEN 1 ELSE 0 END), 0)      AS acceptedCount,
    COUNT(DISTINCT s.user_id)                                       AS activeStudentCount,
    COUNT(DISTINCT s.problem_id)                                    AS problemCount
FROM submission s
INNER JOIN class_student cs ON cs.student_id = s.user_id AND cs.class_id = #{classId}
WHERE s.create_time >= #{from}
  AND s.create_time <  #{to}


SELECT
    DATE_FORMAT(s.create_time, '%Y-%m-%d') AS submitDate,
    COUNT(*)                                AS submitCount,
    COALESCE(SUM(CASE WHEN s.status = 1 THEN 1 ELSE 0 END), 0) AS acCount
FROM submission s
INNER JOIN class_student cs ON cs.student_id = s.user_id AND cs.class_id = #{classId}
WHERE s.create_time >= #{from}
  AND s.create_time <  #{to}
GROUP BY DATE_FORMAT(s.create_time, '%Y-%m-%d')
ORDER BY submitDate ASC
